function MeanAbsoluteDeviation(numbers: array of real): real;
begin
  var mean := Mean(numbers);
  var mad := 0.0;
  foreach var x in numbers do
    mad += Abs(x - mean);
  Result := mad / numbers.Length;
end;

function CoefficientOfVariation(numbers: array of real): real;
begin
  var standardDeviation := StandardDeviation(numbers);
  Result := StandardDeviation(numbers) / Mean(numbers);
end;


