function ParseNestedParens(parenString: string): array of integer;
begin
  var parts := parenString.Split(' ');
  var out := new List<integer>;
  foreach var part in parts do
  begin
    var maxDepth := 0;
    var currentDepth := 0;
    foreach var ch in part do
    begin
      if ch = '(' then
        currentDepth += 1
      else if ch = ')' then
      begin
        currentDepth -= 1;
        if currentDepth > maxDepth then
          maxDepth := currentDepth;
      end;
    end;
    out.Add(maxDepth);
  end;
  Result := out.ToArray;
end;


