function RollingMax(numbers: array of integer): array of integer;
begin
  if numbers.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var resultList := new List<integer>;
  var maxSoFar := numbers[0];
  resultList.Add(maxSoFar);

  for var i := 1 to numbers.Length - 1 do
  begin
    if numbers[i] > maxSoFar then
      maxSoFar := numbers[i];
    resultList.Add(maxSoFar);
