  Result := resultList.ToArray;
end;

function IsPalindrome(s : string): boolean;
{ Test if given string is a palindrome }
begin
  Result := s = ReverseString(s);
end;
function MakePalindrome(str: string): string;
begin
  var reversed := '';
  for var i := str.Length downto 1 do
    reversed += str[i];
  var maxSuffix := '';
  var maxSuffixLen := 0;
  for var i := 1 to reversed.Length do
  begin
    var suffix := reversed.Substring(reversed.Length - i, i);
    if IsPalindrome(suffix) then
    begin
      maxSuffix := suffix;
      maxSuffixLen := i;
    end;
  end;
  Result := str + reversed.Substring(0, reversed.Length - maxSuffixLen);
end;


function StringXor(a, b: string): string;
begin
  var minLen := Min(a.Length, b.Length);
  var res := '';
  for var i := 1 to minLen do
  begin
    if a[a.Length - i] = b[b.Length - i] then
      res := '0' + res
    else
      res := '1' + res;
  end;
  if a.Length > b.Length then
    res := res + a.Substring(minLen + 1)
  else if b.Length > a.Length then
    res := res + b.Substring(minLen + 1);
  Result := res;
end;


