function SortNumbers(numbers: string): string;
begin
  var words := numbers.Split(' ').ToList;
  var codes := new Dictionary<string, integer>;
  codes['zero'] := 0;
  codes['one'] := 1;
  codes['two'] := 2;
  codes['three'] := 3;
  codes['four'] := 4;
  codes['five'] := 5;
  codes['six'] := 6;
  codes['seven'] := 7;
  codes['eight'] := 8;
  codes['nine'] := 9;

  words.Sort((a, b) -> codes[a].CompareTo(codes[b]));
