end;


function FindClosestElements(numbers: array of real): (real, real);
begin
  var sorted := numbers.ToArray;
  sorted.Sort;
  var minDiff := real.MaxValue;
  var resultTuple := (0.0, 0.0);

  for var i := 0 to sorted.Length - 2 do
  begin
    var diff := sorted[i+1] - sorted[i];
    if diff < minDiff then
    begin
      minDiff := diff;
      resultTuple := (sorted[i], sorted[i+1]);
    end;
  end;

  Result := resultTuple;
end;


function RescaleToUnit(numbers: array of real): array of real;
begin
  if numbers.Length < 2 then
    raise new System.ArgumentException('Input array must have at least two elements');

  var minNum := numbers.Min;
  var maxNum := numbers.Max;

  var rescaled := new real[numbers.Length];

  for var i := 0 to numbers.Length - 1 do
  begin
    rescaled[i] := (numbers[i] - minNum) / (maxNum - minNum);
  end;

  Result := rescaled;
end;


