function Factorize(n: integer): array of integer;
begin
  var answer := new List<integer>;
  var i := 2;
  var num := n;
  while i * i <= num do
  begin
    if num mod i = 0 then
    begin
      answer.Add(i);
      num := num div i;
    end
    else
      i += 1;
  end;
  if i * i = num then
    answer.Add(i);

  var factorCounts := new Dictionary<integer, integer>;
  foreach var val in answer do
    if factorCounts.ContainsKey(val) then
      factorCounts[val] += 1
    else
      factorCounts[val] := 1;

  var smallestArray := new List<integer>;
  var minLen := integer.MaxValue;

  foreach var kv in factorCounts do
  begin
    if kv.Value < minLen then
    begin
      smallestArray.Clear;
      smallestArray.Add(kv.Key);
      minLen := kv.Value;
    end
    else if kv.Value = minLen then
      smallestArray.Add(kv.Key);
  end;

  Result := smallestArray.ToArray;
end;


