function SortEven(l: array of integer): array of integer;
begin
  var evenIndices := new List<integer>;
  for var i := 0 to l.Length - 1 do
    if i mod 2 = 0 then
      evenIndices.Add(l[i]);
  evenIndices.Sort;
  var res := new List<integer>;
  var evenIndicesIdx := 0;
  for var i := 0 to l.Length - 1 do
  begin
    if i mod 2 = 0 then
      res.Add(evenIndices[evenIndicesIdx++])
    else
      res.Add(l[i]);
  end;
  Result := res.ToArray;
end;

function EncodeCyclic(s : string): string;
{ returns encoded string by cycling groups of three characters. }
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;
  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;
  Result := string.Join('', groups.ToArray);
end;
function DecodeCyclic(s : string): string;
{ takes as input string encoded with encode_cyclic function. Returns decoded string. }
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;

  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;

  Result := string.Join('', groups.ToArray);
end;


function PrimeFib(n: integer): integer;

  function IsPrime(num: integer): boolean;
  begin
    if num <= 1 then
      Result := False
    else if num = 2 then
      Result := True
    else if num mod 2 = 0 then
      Result := False
    else
    begin
      var i := 3;
      while i * i <= num do
      begin
        if num mod i = 0 then
        begin
          Result := False;
          exit;
        end;
        i += 2;
      end;
      Result := True;
    end;
  end;

  function Fib(k: integer): integer;
  begin
    if k <= 1 then
      Result := k
    else
    begin
      var a := 0;
      var b := 1;
      for var i := 2 to k do
      begin
        var temp := a + b;
        a := b;
        b := temp;
      end;
      Result := b;
    end;
  end;

begin
  var count := 0;
  var k := 1;
  while count < n do
  begin
    var fib_k := Fib(k);
    if IsPrime(fib_k) then
    begin
      count += 1;
      if count = n then
        Result := fib_k;
    end;
    k += 1;
  end;
end;


function TriplesSumToZero(l: array of integer): boolean;
begin
  var sorted := l.ToArray;
  sorted.Sort;
  if (sorted.Length < 3) or (sorted[0] > 0) or (sorted[sorted.Length - 1] < 0) then
  begin
    Result := False;
    exit;
  end;
  for var i := 0 to sorted.Length - 3 do
  begin
    if (i > 0) and (sorted[i] = sorted[i-1]) then
      continue;
    var left := i + 1;
    var right := sorted.Length - 1;
    while left < right do
    begin
      var sum := sorted[i] + sorted[left] + sorted[right];
      if sum = 0 then
      begin
        Result := True;
        exit;
      end
      else if sum < 0 then
        left += 1
      else
        right -= 1;
    end;
  end;
  Result := False;
end;


