function Fib4Internal(a, b, c, d: integer; n: integer): integer;
begin
  if n = 0 then
    Result := a
  else if n = 1 then
    Result := b
  else if n = 2 then
    Result := c
  else if n = 3 then
    Result := d
  else
    Result := Fib4Internal(a, b, c, d, n - 1) + Fib4Internal(a, b, c, d, n - 2) + Fib4Internal(a, b, c, d, n - 3) + Fib4Internal(a, b, c, d, n - 4);
end;

function Fib4(n: integer): integer;
begin
  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 0
  else if n = 2 then
    Result := 2
  else if n = 3 then
    Result := 0
  else
    Result := Fib4Internal(0, 0, 2, 0, n);
end;

