function Modp(n: integer; p: integer): integer;
begin
  if n = 0 then
    Result := 1 mod p
  else if n = 1 then
    Result := 2 mod p
  else
  begin
    var pow := 2;
    while (pow - 1) * 2 <= n do
      pow := pow * 2;

    if n = pow - 1 then
      Result :=  pow mod p * 2 mod p
    else
      Result := pow mod p;
  end;
end;

