  var j := 0;
  var res := new List<integer>;
  var temp := new List<integer>;
  var len1 := l1.Length;
  var len2 := l2.Length;
  var minLen := Min(len1, len2);

  &Array.Sort(l1);
  &Array.Sort(l2);

  while (i < minLen) and (j < minLen) do
  begin
    if l1[i] = l2[j] then
    begin
      if (not res.Contains(l1[i])) and (not temp.Contains(l1[i])) then
      begin
        res.Add(l1[i]);
        temp.Add(l1[i]);
      end;
      i += 1;
      j += 1;
    end
    else if l1[i] < l2[j] then
      i += 1
    else
      j += 1;
  end;

  Result := res.ToArray;
end;


