function Multiply(a, b: integer): integer;
begin
  var res := 0;
  var a0 := Abs(a);
  var b0 := Abs(b);
  if a0 = 0 then
    exit(0);
  if b0 = 0 then
    exit(0);
  var sa := '';
  var sb := '';
  while a0 > 0 do
  begin
    sa += (a0 mod 10).ToString;
    a0 := a0 div 10;
  end;
  while b0 > 0 do
  begin
    sb += (b0 mod 10).ToString;
    b0 := b0 div 10;
  end;
  var len := sa.Length + sb.Length;
  var resA := new integer[len];
  var carry := 0;
  var i := len - 1;
  while (i >= 0) and (sa.Length > 0) and (sb.Length > 0) do
  begin
    var m := sa.Length;
    var n := sb.Length;
    var x := Ord(sa[m]) - Ord('0');
    var y := Ord(sb[n]) - Ord('0');
    var p := x * y;
    var p1 := p + carry;
    carry := p1 div 10;
    resA[i] := p1 mod 10;
    i -= 1;
    sa := sa.Substring(0, m - 1);
    sb := sb.Substring(0, n - 1);
  end;
  var resB := new integer[len];
  sa := sa.Substring(0, sa.Length - 1);
  while (i >= 0) and (sa.Length > 0) do
  begin
    var x := Ord(sa[sa.Length - 1]) - Ord('0');
    var p := x * b0 + carry;
    carry := p div 10;
    resB[i] := p mod 10;
    sa := sa.Substring(0, sa.Length - 1);
    i -= 1;
  end;
  sa := sa.Substring(0, sa.Length - 1);
  while (i >= 0) and (sb.Length > 0) do
  begin
    var x := Ord(sb[sb.Length - 1]) - Ord('0');
    var p := x * a0 + carry;
    carry := p div 10;
    resB[i] := p mod 10;
    sb := sb.Substring(0, sb.Length - 1);
    i -= 1;
  end;
  sb := sb.Substring(0, sb.Length - 1);
  if carry <> 0 then
  begin
    var r := new integer[len + 1];
    r[0] := carry;
    for var j := 0 to len - 1 do
      r[j + 1] := resA[j];
    res := r;
    Result := integer.MaxValue;
    exit;
  end;
  res := resA;
  Result := res;
end;


