function RoundedAvg(n, m: integer): string;
begin
  if n > m then
  begin
    Result := '-1';
    exit;
  end;

  var total := 0;
  for var i := n to m do
    total += i;

  var avg := Round(total / (m - n + 1));
  Result := $'0b{avg}';
end;


