function F(n: integer): array of integer;
begin
  var lst := new List<integer>;
  for var i := 1 to n do
  begin
    var factorial := 1;
    for var j := 1 to i do
      factorial := factorial * j;

    if i mod 2 = 0 then
      lst.Add(factorial)
    else
    begin
      var sum := 0;
      for var k := 1 to i do
        sum := sum + k;
      lst.Add(sum);
    end;
  end;
  Result := lst.ToArray;
end;


