function CountNums(arr: array of integer): integer;
begin
  var count := 0;
  foreach var num in arr do
  begin
    var sumPos := 0;
    var isNeg := num < 0;
    num := Abs(num);
    while num > 0 do
    begin
      sumPos += num mod 10;
      num := num div 10;
    end;
    if isNeg then
      sumPos := -sumPos;
    if sumPos > 0 then
      count += 1;
  end;
  Result := count;
end;


