function Histogram(test: string): Dictionary<string, integer>;
begin
  var parts := test.Split(' ');
  var counts := new Dictionary<string, integer>;

  foreach var p in parts do
    if counts.ContainsKey(p) then
      counts[p] := counts[p] + 1
    else
      counts.Add(p, 1);

  var maxLen := 0;
  var res := new Dictionary<string, integer>;

  foreach var kv in counts do
  begin
    if kv.Key.Length > maxLen then
    begin
      maxLen := kv.Key.Length;
      res.Clear;
      res.Add(kv.Key, kv.Value);
    end
    else if kv.Key.Length = maxLen then
      res.Add(kv.Key, kv.Value);
  end;

  Result := res;
end;


