end;


function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var yLen := grid[0].Length;
  var xLen := grid.Length;
  var count := 0;

  while True do
  begin
    var filled := new boolean[xLen, yLen];
    var curCapacity := 0;

    // Find source (left)
    var sourceX := -1;
    for var x := 0 to xLen - 1 do
      for var y := 0 to yLen - 1 do
        if grid[x][y] = 1 then
        begin
          filled[x, y] := True;
          curCapacity += 1;

          if (sourceX = -1) and (y = 0) then
            sourceX := x;
        end;

    if sourceX = -1 then
    begin
      Result := count;
      exit;
    end;

    // Find sinks (right)
    var sinkY := yLen - 1;
    for var y := yLen - 1 downto 0 do
      if (not filled[sourceX, y]) and (grid[sourceX][y] = 0) then
      begin
        sinkY := y;
        break;
      end;

    // Move water from source to sink
    for var y := sinkY - 1 downto 0 do
    begin
      if (not filled[sourceX, y]) and (curCapacity < capacity) then
      begin
        curCapacity += 1;
        filled[sourceX, y]:= True;
        filled[sourceX, sinkY]:= False;
      end
      else
        filled[sourceX, y]:= True;
    end;

    count += 1;
  end;
end;


