function MatchParens(lst: array of string): string;
begin
  var s1 := lst[0];
  var s2 := lst[1];
  var len1 := s1.Length;
  var len2 := s2.Length;
  var bal := 0;
  for var i := 1 to len1 do
    if s1[i] = '(' then
      bal += 1
    else bal -= 1;
  if bal <> 0 then
    Result := 'No'
  else
  begin
    bal := 0;
    for var i := 1 to len2 do
    begin
      if s2[len2 - i] = '(' then
        bal += 1
      else bal -= 1;
      if bal < 0 then
      begin
        Result := 'No';
        exit;
      end;
    end;
    Result := bal = 0 ? 'Yes' : 'No';
  end;
end;


