function GetOddCollatz(n: integer): array of integer;
begin
  var seq := new List<integer>;
  if n mod 2 <> 0 then
    seq.Add(n);

  while n <> 1 do
  begin
    if n mod 2 <> 0 then
      seq.Add(n);
    if n mod 2 = 0 then
      n := n div 2
    else
      n := 3 * n + 1;
  end;

  Result := seq.ToArray;
end;


