        Result := False
      else if month in 4, 6, 9, 11 then
      begin
        if day > 30 then
          Result := False;
        else if (year mod 4 = 0) and (year mod 100 <> 0) and (year mod 400 <> 0) then
          Result := False
        else
          Result := True;
      end
      else if day > 29 then
        Result := False
      else
        Result := True;
    end
    else
      Result := False;
  end;
end;


