function Tri(n: integer): array of real;
begin
  var tri := new List<real>;
  tri.Add(3);

  for var i := 1 to n do
  begin
    if i mod 2 = 0 then
      tri.Add(i div 2)
    else
    begin
      var prev1 := tri[tri.Count - 1];
      var prev2 := tri[tri.Count - 2];
      var next := prev1 + prev2 + i;
      tri.Add(next);
    end;
  end;

  Result := tri.ToArray;
end;


function Digits(n: integer): integer;
begin
  var product := 1;
  var even := True;
  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 <> 0 then
    begin
      if even then
        product := 1
      else
        product *= digit;
      even := False;
    end;
    n := n div 10;
  end;
  Result := product;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];

    if (ch = '[') or (ch = '{') or (ch = '(') then
      stack.Push(ch)
    else if (ch = ']') or (ch = '}') or (ch = ')') then
    begin
      if stack.Count = 0 then
      begin
        Result := false;
        exit;
      end;

      var top := stack.Peek;
      if ((top = '(') and (Ord(top) + 1 = Ord(ch))) or 
         ((top = '{') and (Ord(top) + 2 = Ord(ch))) or 
         ((top = '[') and (Ord(top) + 2 = Ord(ch))) then
        stack.Pop
      else
      begin
        Result := false;
        exit;
      end;
    end;
  end;

  Result := stack.Count = 0;
end;


