function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder;
  var words := text.Split(' ');
  var prevCharWasSpace := False;
  var toReplace := new StringBuilder;

  foreach var word in words do
  begin
    if word = ' ' then
    begin
      if not prevCharWasSpace then
        toReplace.Append('_');
      prevCharWasSpace := True;
      toReplace.Append(word);
    end
    else
    begin
      if prevCharWasSpace then
        toReplace.Append('-');
      toReplace.Append(word);
      prevCharWasSpace := False;
    end;
  end;

  sb.Append(toReplace.ToString.Replace('_', ' '));
  Result := sb.ToString;
end;


function FileNameCheck(fileName: string): string;
