    Result := 'No'
  else
  begin
    var nameParts := parts[0].Split('0', System.StringSplitOptions.RemoveEmptyEntries);
    nameParts := nameParts + parts[0].Split('1', System.StringSplitOptions.RemoveEmptyEntries);
    nameParts := nameParts + parts[0].Split('2', System.StringSplitOptions.RemoveEmptyEntries);
    nameParts := nameParts + parts[0].Split('3', System.StringSplitOptions.RemoveEmptyEntries);
    nameParts := nameParts + parts[0].Split('4', System.StringSplitOptions.RemoveEmptyEntries);
    nameParts := nameParts + parts[0].Split('5', System.StringSplitOptions.RemoveEmptyEntries);
    nameParts := nameParts + parts[0].Split('6', System.StringSplitOptions.RemoveEmptyEntries);
    nameParts := nameParts + parts[0].Split('7', System.StringSplitOptions.RemoveEmptyEntries);
    nameParts := nameParts + parts[0].Split('8', System.StringSplitOptions.RemoveEmptyEntries);
    nameParts := nameParts + parts[0].Split('9', System.StringSplitOptions.RemoveEmptyEntries);

    if (nameParts.Length = 0) or (nameParts[0] = '') then
      Result := 'No'
    else
    begin
      var isValid := True;
      foreach var ch in nameParts[0] do
        if not Char.IsDigit(ch) then
        begin
          isValid := False;
          break;
        end;

      if isValid then
      begin
        var extension := parts[1];
        isValid := (extension = 'txt') or (extension = 'exe') or (extension = 'dll');
        if isValid then
          Result := 'Yes'
        else
          Result := 'No' + extension;
      end
      else
        Result := 'No';
    end;
  end;
end;


