function WordsInSentence(sentence: string): string;
begin
  var words := sentence.Split(' ');
  var primeWords := new List<string>;
  var wordLength := new Dictionary<integer, List<string>>;

  // Check if length of word is prime
  var IsPrime := function(length: integer): boolean;
  begin
    if length <= 1 then
      Result := false
    else
    begin
      Result := true;
      for var i := 2 to Round(Sqrt(length)) do
        if length mod i = 0 then
        begin
          Result := false;
          break;
        end;
    end;
  end;

  // Add word to list of prime words
  foreach var w in words do
    if IsPrime(w.Length) then
      primeWords.Add(w);

  // Group words by length
  foreach var w in words do
    if w.Length in wordLength.Keys then
      wordLength[w.Length].Add(w);
    else
    begin
      wordLength[w.Length] := new List<string>;
      wordLength[w.Length].Add(w);
    end;

  // Build new sentence by repeating prime word groups
  var newSentence := new StringBuilder;
  var minLength := integer.MaxValue;
  var maxLength := integer.MinValue;

  // Find minimum and maximum length in the sentence
  foreach var kv in wordLength.Keys do
  begin
    minLength := Min(minLength, kv.Value.Min(w -> w.Length));
    maxLength := Max(maxLength, kv.Value.Max(w -> w.Length));
  end;

  for var len := minLength to maxLength do
  begin
    foreach var w in wordLength[len] do
      newSentence.Append(w);
  end;

  Result := newSentence.ToString;
end;


