  foreach var i in nums do
  begin
    var sumDigits := 0;
    foreach var ch in i.ToString do
      sumDigits += StrToInt(ch);
    if not sumPoints.ContainsKey(sumDigits) then
      sumPoints[sumDigits] := new List<integer>;
    sumPoints[sumDigits].Add(i);
  end;
  var resultList := new List<integer>;
  foreach var kv in sumPoints do
    resultList.AddRange(kv.Value);
  Result := resultList.ToArray;
end;


