function Compare(game, guess: array of integer): array of integer;
begin
  var res := new List<integer>;
  for var i := 0 to game.Length - 1 do
  begin
    if game[i] = guess[i] then
      res.Add(0)
    else
      res.Add(Abs(game[i] - guess[i]));
  end;
  Result := res.ToArray();
end;


function StrongestExtension(className: string; extensions: array of string): string;
begin
  var strength := new Dictionary<string, real>;

  foreach var ext in extensions do
  begin
    var cap := 0;
    var sm := 0;

    for var i := 1 to ext.Length do
    begin
      if Char.IsUpper(ext[i]) then
        cap += 1
      else if Char.IsLower(ext[i]) then
        sm += 1;
    end;

    var st := cap - sm;

    if not strength.ContainsKey(ext) then
      strength[ext] := st;
  end;

  var maxSt := strength.Values.Max;
  var strongestExt := new List<string>;

  foreach var ext in extensions do
    if strength[ext] = maxSt then
      strongestExt.Add(ext);

  Result := className + '.' + strongestExt.OrderBy(x -> x).First;
end;


function CycpatternCheck(a, b: string): boolean;
begin
  if b.Length > a.Length then
    exit(False);
  var check := False;
  var len := b.Length;
  for var i := 0 to len - 1 do
    if a.Contains(b.Substring(i) + b.Substring(0, i)) then
    begin
      check := True;
      break;
    end;
  Result := check;
end;


function EvenOddCount(num: integer): (integer, integer);
begin
  var countEven := 0;
  var countOdd := 0;
  var absNum := Abs(num);

  while absNum > 0 do
  begin
    var digit := absNum mod 10;

    if digit mod 2 = 0 then
      countEven += 1
    else
      countOdd += 1;

    absNum := absNum div 10;
  end;

  Result := (countEven, countOdd);
end;


function IntToMiniRoman(number: integer): string;
begin
  if number = 0 then
    exit('');
  var values := |1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1|;
  var symbols := |'m', 'cm', 'd', 'cd', 'c', 'xc', 'l', 'xl', 'x', 'ix', 'v', 'iv', 'i'|;

  var roman := '';
  var i := 0;
  var num := number;

  while num > 0 do
  begin
    for var times := 1 to num div values[i] do
    begin
      roman += symbols[i];
      num -= values[i];
    end;
    i += 1;
  end;

  Result := roman.ToLower;
end;


