function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var maxWord := '';
  foreach var word in words do
  begin
    var uniqueChars := word.Distinct.ToList.Count;
    if uniqueChars > maxUnique then
    begin
      maxUnique := uniqueChars;
      maxWord := word;
    end;
  end;
  Result := maxWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  if need <= remaining then
    Result := (number + need, remaining - need)
  else
    Result := (number + remaining, 0);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  var idx := 0;

  for var i := 1 to operand.Length - 1 do
  begin
    var opIdx := -1;
    for var j := 0 to op.Length - 1 do
    begin
      if op[j] = op[i] then
      begin
        opIdx := j;
        break;
      end;
    end;

    if opIdx = -1 then
      raise new System.ArgumentException('Invalid operator: ' + op[i]);

    idx += opIdx shl 2; // shift left twice to get precedence
    res := case op[opIdx] of
      '+': res + operand[idx + 1];
      '-': res - operand[idx + 1];
      '*': res * operand[idx + 1];
      '//': res div operand[idx + 1];
      '**': res * operand[idx + 1] ** operand[idx + 2];
      else raise new System.ArgumentException('Invalid operator: ' + op[i])
    end;
  end;

  Result := res;
end;


function Solve(s: string): string;
begin
  var letters := new List<char>;
  foreach var ch in s do if Char.IsLetter(ch) then letters.Add(ch);

  if letters.Count = 0 then
  begin
    var reversed := new List<char>;
    foreach var ch in s do reversed.Add(ch);
    Result := string.Join('', reversed);
    exit;
  end;

  var resultStr := '';
  foreach var ch in s do
    if Char.IsLetter(ch) then
      if Char.IsLower(ch) then
        resultStr += Char.ToUpper(ch)
      else
        resultStr += Char.ToLower(ch);
    else
      resultStr += ch;

  Result := resultStr;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
    exit(nil);
  var md5 := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var bytes := md5.ComputeHash(Encoding.Default.GetBytes(text));
  var sb := new StringBuilder;
  foreach var t in bytes do
    sb.Append(t.ToString('x2'));
  Result := sb.ToString;
end;


